    function renderNiCoShipping(){const lots=shippingLots(),verified=lots.filter(lot=>['VERIFIED','PACKING_LIST_READY'].includes(lot.status));byId('nicoShippingSummary').innerHTML=`<div><small>출하대기 LOT</small><b>${lots.length}건</b></div><div><small>확인완료 LOT</small><b>${verified.length}건</b></div><div><small>총 중량</small><b>${weight(lots.reduce((sum,lot)=>sum+numeric(lot.weight),0))}</b></div>`;if(!currentShipLotId&&lots[0])currentShipLotId=lots[0].id;byId('nicoShippingLots').innerHTML=lots.length?lots.map(lot=>{const selected=lot.id===currentShipLotId,done=['VERIFIED','PACKING_LIST_READY'].includes(lot.status),checked=lot.items.filter(item=>item.verified).length;return`<article class="nico-lot-card ${selected?'':'nico-invalid'}"><div class="actions" style="justify-content:space-between"><span class="status-chip ${done?'':'warn'}">${done?'확인완료':'확인대기'} ${checked}/${lot.items.length}</span><button class="btn ${selected?'primary':''}" onclick="selectNiCoShippingLot('${lot.id}')">LOT 재고 선택</button></div><h2>${safe(lot.lotNo)} · ${weight(lot.weight)}</h2><p>Ni ${numeric(lot.ni).toFixed(2)}% · Co ${numeric(lot.co).toFixed(2)}% · Powder ${weight(lot.powderWeight)}</p>${selected?`<div>${lot.items.map(item=>`<label class="nico-stock-row"><input type="checkbox" ${item.verified?'checked':''} onchange="toggleNiCoShippingItem('${lot.id}','${safe(item.key)}',this.checked)"><span><b>${safe(item.completionNo)} · ${safe(item.grade)}</b><br>${weight(item.weight)}${item.verified?' · 확인완료':''}</span></label>`).join('')}</div><button class="btn primary" style="width:100%" onclick="saveNiCoLotVerification('${lot.id}')">이 LOT 완료저장</button>`:''}</article>`}).join(''):'<div class="card">Ni Co 용해 LOT 완료자료가 없습니다.</div>';const allDone=lots.length&&lots.every(lot=>['VERIFIED','PACKING_LIST_READY'].includes(lot.status));byId('nicoPackingListCreate').disabled=!allDone||lots.every(lot=>lot.status==='PACKING_LIST_READY')}
